import{z as B,x as i,o as E,c as p,q as s,j as o,D as e,d as t,s as n,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"自投机与多 token 头","description":"","frontmatter":{"title":"自投机与多 token 头","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-self-draft-medusa.md","filePath":"llm/spec-self-draft-medusa.md","lastUpdated":1791063341000}'),d={name:"llm/spec-self-draft-medusa.md"};function m(C,a,c,D,h,f){const A=i("Mermaid");return E(),p("div",null,[a[2]||(a[2]=s('<h1 id="自投机与多-token-头" tabindex="-1">自投机与多 token 头 <a class="header-anchor" href="#自投机与多-token-头" aria-label="Permalink to &quot;自投机与多 token 头&quot;">​</a></h1><div class="epigraph"><p>最便宜的草稿不是更小的模型，而是目标自己：表示里本来就压着对未来若干位置的猜测，缺的只是几个把它取出来的头。</p><footer>—— 据 Cai et al., Medusa, ICML 2024 与 Leviathan et al., 2023 的草稿供给侧口径整理</footer></div><p><a href="/llm/num-map">上一课</a>把数值精度收成八步决策单与一份预算表：格式怎么分工、scale 怎么乘、每一档精度花多少钱，推理侧的深钻交了卷。预算表算清了每个 token 的钱，本课程问怎么让同样的钱吐出更多 token——第一课从草稿供给侧的谱系开始。<a href="/llm/speculative-decoding">投机解码原理</a>把草稿留成了一个自由接口，<a href="/llm/draft-model">草稿模型选择</a>讨论过养一个独立小模型的成本：另训、跟版、对齐词表与模板。本课写把草稿收回目标自己的两条路：浅层提前退出的自投机，与挂在骨干上的多 token 头。特征级自回归的 Eagle 一族留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立草稿模型的成本不只是参数量。词表与分词必须逐一对齐，采样截断与对话模板必须同步升级；目标每发一版，配对就重来一遍。更根本的缺口是信息浪费：目标的前向刚刚算出 \\(h_t\\)，这个表示已经「知道」不少关于 \\(t+1\\) 之后的结构，投机却要另起炉灶从零猜。自投机的命题是：让同一套权重或同一份表示兼任草稿，把对齐成本一次性清零——词表、模板、采样器按构造就一致。</p><p><span class="marginnote">直觉类比：养独立草稿模型像再雇一位翻译，术语表、行文风格都要重新对齐，主翻译每次改稿他都得跟着重学；自投机像让主翻译自己先出快稿再润色——术语口音天然一致，缺的只是快稿的准头。</span></p><p>代价也按构造出现：草稿与目标共享计算，草稿的独立性下降，接受率的上限由「表示里还剩多少未被下一词耗尽的远位信息」决定。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>浅层提前退出</strong>。把前 \\(k\\) 层当草稿 \\(q\\)、全栈当目标 \\(p\\)：浅层分布先行采样，分歧时用全栈校验修正，接受规则仍是<a href="/llm/speculative-sampling">投机采样</a>的似然比。实现要点在退出判据：浅层与深层分布的 KL 或 top-token 置信度过阈值才直接提交，否则交全栈。骨干若未经改造，浅层分布质量有限，配合浅层丢弃一类训练才能把 \\(k\\) 推深——口径见<a href="/llm/self-speculative-decoding">自投机解码</a>。</p><p><strong>多 token 头</strong>。骨干最后隐状态 \\(h_t\\) 上接 \\(K\\) 个轻量头，第 \\(k\\) 个头直接预测 \\(t+k+1\\)：一次前向同时打出未来 \\(K\\) 个位置的分布，不再串行。各头取 top-\\(s_k\\) 做笛卡尔积收成一棵 token 树，树注意力一次校验，无损性由拒绝采样保证——这就是 <a href="/llm/medusa">Medusa</a> 的骨架。训练用目标自己的输出自蒸馏，冻结骨干则骨干下一词能力不动；联合训练要靠学习率与蒸馏损失护住骨干。</p><p><span class="marginnote">数字实例：5 个头各取 top-3，笛卡尔积是 \\(3^5=243\\) 个候选节点；就算每头砍到 top-2，也还有 \\(2^5=32\\) 个。树宽是按头的个数指数长的——这正是「树宽要随批量收」的算术来源。</span></p>',11)),(E(),o(r,null,{default:e(()=>[n(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%AA%A8%E5%B9%B2%E9%9A%90%E7%8A%B6%E6%80%81%20h_t%22%5D%20--%3E%20P0%5B%22%E5%8E%9F%20LM%20%E5%A4%B4%EF%BC%9At%2B1%22%5D%0A%20%20H%20--%3E%20K1%5B%22%E5%A4%B4%201%EF%BC%9At%2B2%22%5D%0A%20%20H%20--%3E%20K2%5B%22%E5%A4%B4%202%EF%BC%9At%2B3%22%5D%0A%20%20P0%20--%3E%20TREE%5B%22%E5%90%84%E5%A4%B4%20top-s%20%E7%AC%9B%E5%8D%A1%E5%B0%94%E7%A7%AF%E6%88%90%E6%A0%91%22%5D%0A%20%20K1%20--%3E%20TREE%0A%20%20K2%20--%3E%20TREE%0A%20%20TREE%20--%3E%20V%5B%22%E6%A0%91%E6%B3%A8%E6%84%8F%E5%8A%9B%E4%B8%80%E6%AC%A1%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20V%20--%3E%20A%5B%22%E6%8C%89%E4%BC%BC%E7%84%B6%E6%AF%94%E6%8E%A5%E5%8F%97%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"两条路赚的都是「草稿近于免费」：提前退出的草稿省掉了深层的 FLOPs 与权重读，多 token 头的草稿省掉了整段串行前向——\\(K\\) 个头只是几个矩阵乘。无损性都继承自同一个接受规则，本课不重证。真正的机制约束在表示侧：\\(h_t\\) 对下一词是充分统计量，对下下词不是。多 token 头是在「下一词语境」里盲猜更远的位置，位置每远一步，头与目标的对齐就掉一截，所以远位头单独看几乎不可用，必须靠树把「第一步就对了」的路径上的远位猜测一起兑现——树把条件独立假设的误差从链上挪到了分支选择上。这也预告了下一课的缺口：若草稿能在特征层自回归，远位对齐不必靠盲猜。",-1)),(E(),o(r,null,{default:e(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%9C%E4%BD%8D%E5%A4%B4%E4%B8%BA%E4%BD%95%E5%8D%95%E7%8B%AC%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%AF%E7%94%A8%3F%22%5D%20--%3E%20H%5B%22%E5%A4%B4%202%20%E5%9C%A8%20t%2B1%20%E8%AF%AD%E5%A2%83%E9%87%8C%E7%9B%B2%E7%8C%9C%20t%2B3%22%5D%0A%20%20H%20--%3E%20CASE%7B%22t%2B1%20%E8%A2%AB%E7%9B%AE%E6%A0%87%E6%8E%A5%E5%8F%97%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20CASE%20--%3E%7C%22%E5%AF%B9%E4%BA%86%22%7C%20GOOD%5B%22t%2B3%20%E7%9A%84%E7%8C%9C%E8%B7%AF%E5%BE%84%E6%88%90%E7%AB%8B%2C%20%E5%8F%AF%E5%85%91%E7%8E%B0%22%5D%0A%20%20CASE%20--%3E%7C%22%E9%94%99%E4%BA%86%22%7C%20BAD%5B%22t%2B3%20%E7%9A%84%E7%8C%9C%E6%B5%8B%E8%B7%9F%E7%9D%80%E6%8A%A5%E5%BA%9F%22%5D%0A%20%20GOOD%20--%3E%20T%5B%22%E6%A0%91%E6%8A%8A%E7%AC%AC%E4%B8%80%E6%AD%A5%E4%B8%8E%E8%BF%9C%E4%BD%8D%E7%8C%9C%E6%89%93%E5%8C%85%E6%88%90%E6%9E%9D%22%5D%0A%20%20BAD%20--%3E%20T%0A%20%20T%20--%3E%20V%5B%22%E6%A0%A1%E9%AA%8C%E5%8F%AA%E5%85%91%E7%8E%B0%E7%AC%AC%E4%B8%80%E6%AD%A5%E6%AD%A3%E7%A1%AE%E7%9A%84%E9%82%A3%E6%9D%A1%E6%9E%9D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">Medusa 的主实验在 batch=1 的本地托管下报 2–3 倍区间；高并发下校验树的额外 token 会稀释收益，树宽要随批量收。读加速比先看批量，再问温度，最后才看倍数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自投机要求访问目标权重与训练数据：提前退出的判据要在目标上校准，多 token 头要用目标自己的输出做蒸馏，闭源目标上无从谈起。联合训练是超参敏感区：头损失权重过大或学习率失配，骨干的下一词质量会被拖下水，加速没换来，质量先亏了。Medusa 还给出 typical acceptance 一类放宽变体，用「够像」替代精确拒绝采样换更长接受——那是有偏加速，分布一致性不再成立，必须单独声明。浅层提前退出的 \\(k\\) 与阈值是逐模型超参，换档重配。</p><p><span class="marginnote">常见误区：以为第 5 个头「能预测 5 步之后」很神奇。单个远位头的独立命中率其实很低；它真正出场的方式，是前几步恰好全对的那条枝上顺势兑现——赚的是一条链的联合概率，不是单点准确率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自投机把草稿收回目标自己：浅层提前退出当 \\(q\\)、全栈当 \\(p\\)，或多 token 头一次打出未来 \\(K\\) 个位置。</li><li>词表、模板、采样器按构造对齐，配对与跟版成本清零；草稿本身的计算近于免费。</li><li>表示约束是共同上限：\\(h_t\\) 只对下一词充分，远位头靠树兑现，条件独立的误差转移到分支选择。</li><li>无损性仍由拒绝采样保证；typical acceptance 一类放宽是有偏变体，须单独声明。</li><li>训练是被低估的成本：蒸馏数据、头损失权重、退出阈值都逐模型校准。</li><li>出处：Cai et al., <em>Medusa</em>, ICML 2024；Leviathan et al., ICML 2023；自投机口径据本仓库投机课序。</li></ul>',6))])}const _=B(d,[["render",m]]);export{k as __pageData,_ as default};
